    with pytest.raises(MissingChannelError) as excinfo:
        await backend.connect()
    assert "voltage_measurement_range" in str(excinfo.value)
    assert "SENS:VOLT:RANG?" in str(excinfo.value)
    assert not fake.is_open, "a failed connect must not leave a socket holding a connection slot"


