@sync
async def test_frame_measures_once_and_fetches_the_rest():
    """MEASure performs the acquisition and the two FETCh queries read the same
    one, so voltage, current and power describe a single instant. Measuring each
    separately would cost twice as long and give three."""
    backend, fake = await connected_backend()
    fake.messages.clear()
    await backend._read_frame()
    parts = fake.messages[0].split(SEPARATOR)
    assert parts.count("MEAS:VOLT?") == 1
    assert "MEAS:CURR?" not in parts and "MEAS:POW?" not in parts
    assert parts.index("MEAS:VOLT?") < parts.index("FETC:CURR?") < parts.index("FETC:POW?")


