@sync
async def test_frame_decodes_the_status_registers():
    """The recorded questionable condition is 8192 - bit 13, a sense-lead fault,
    which is what an unstrapped sense terminal reads as. The operation condition
    is 4: bit 2, output programmed off."""
    backend, _ = await connected_backend()
    frame = await backend._read_frame()
    assert frame["questionable_status"] == 8192
    assert frame["sense_fault"] is True
    assert frame["tripped_ov"] is False
    assert frame["tripped_oc"] is False
    assert frame["operation_status"] == 4
    assert frame["output_off"] is True
    assert frame["in_cv"] is False
    assert frame["questionable2_status"] == 0
    assert frame["tripped_user_protection"] is False


@sync
async def test_event_channels_come_from_the_event_registers_not_the_conditions():
    """A condition that merely stands does not set its event bit, so the two
    must be read and decoded separately: the event bit is an edge."""
    replies = dict(RECORDED_REPLIES)
    replies["STAT:QUES:COND?"] = "+0"      # nothing true now
    replies["STAT:QUES:EVEN?"] = "+2"      # but over-current tripped and cleared
    backend, _ = await connected_backend(fake=FakeInstrument(replies=replies))
    frame = await backend._read_frame()
    assert frame["tripped_oc"] is False, "the condition register says it is not tripped now"
    assert frame["tripped_oc_event"] is True, "the event register says it tripped since the last frame"
    assert frame["sense_fault"] is False and frame["sense_fault_event"] is False


