@sync
async def test_a_single_failed_frame_is_dropped_rather_than_fatal():
    """The transport has already reopened the link by the time it raises, so one
    bad frame costs a gap in the record and not a run."""
    backend, fake = await connected_backend()
    fake.extra_value = True
    for _ in range(MAX_CONSECUTIVE_FRAME_FAILURES - 1):
        assert await backend._read_frame() is None
    with pytest.raises(HardwareError, match="frames in a row failed"):
        await backend._read_frame()


@sync
async def test_the_failure_counter_resets_after_a_good_frame():
    backend, fake = await connected_backend()
    fake.extra_value = True
    assert await backend._read_frame() is None
    fake.extra_value = False
    assert await backend._read_frame() is not None
    fake.extra_value = True
    assert await backend._read_frame() is None, "one earlier failure must not count against this one"


