@sync
async def test_a_write_checks_its_error_then_reads_back_in_a_second_message():
    """The readback cannot share the write's message: on this instrument a
    setting query alongside the write that changes it answers one step stale."""
    backend, fake = await connected_backend()
    fake.messages.clear()
    applied = await backend.execute("set_voltage", value=12.0)
    assert fake.messages == ["VOLT 12.0;:SYST:ERR?", "VOLT?"]
    # The readback is the instrument's answer, not the value that was sent.
    assert applied == pytest.approx(0.08)


