@sync
async def test_a_recalled_state_outside_the_limits_raises_after_it_is_applied():
    """A store's contents are unknown until it is loaded, so this cannot be
    clamped. The message has to say the values are already applied."""
    replies = dict(RECORDED_REPLIES)
    replies["CURR:LIM:NEG?"] = "-2.000000E+01"  # beyond one dissipator's -12.75 A
    backend, _ = await connected_backend(fake=FakeInstrument(replies=replies))
    with pytest.raises(HardwareError) as excinfo:
        await backend.execute("recall_state", value=0)
    assert "NOW APPLIED" in str(excinfo.value)
    assert "current_limit_negative" in str(excinfo.value)


