def test_every_client_method_calls_a_declared_action():
    """The client is a hand-written façade over a generated action list, so a
    renamed action would otherwise leave a method calling something that no
    longer exists - which verify_actions() cannot catch, because it checks the
    names a caller asks for, not the ones the façade sends."""
    import inspect
    import re

    from hardware.n6974a import n6974a_command_client as module

    declared = set(COMMAND_CHANNELS)
    source = inspect.getsource(module)
    # execute("literal") and execute(f"prefix_{index}")
    literals = set(re.findall(r'self\.execute\(\s*"([a-z0-9_]+)"', source))
    templates = set(re.findall(r'self\.execute\(\s*f"([a-z0-9_]+)\{', source))
    unknown = literals - declared
    assert not unknown, f"client methods call undeclared actions: {sorted(unknown)}"
    for prefix in templates:
        assert any(action.startswith(prefix) for action in declared), \
            f"no declared action begins with {prefix!r}"


@sync
async def test_a_link_that_closes_unbidden_is_a_failure_not_silence():
    """The transport closes the socket itself to resynchronise and leaves it
    closed if reopening failed. Treating that as 'disconnected' would leave the
    driver alive and publishing nothing for the rest of the run."""
    backend, fake = await connected_backend()
    await fake.close()
    for _ in range(MAX_CONSECUTIVE_FRAME_FAILURES - 1):
        assert await backend._read_frame() is None
    with pytest.raises(HardwareError, match="did not close it"):
        await backend._read_frame()


