@pytest.mark.parametrize("pin,function,allowed", [
    (1, "FAUL", True), (2, "FAUL", False), (3, "FAUL", False),
    (3, "INH", True), (1, "INH", False), (7, "INH", False),
    (4, "ONC", True), (7, "OFFC", True), (1, "ONC", False), (2, "OFFC", False),
    (1, "DIO", True), (7, "TINP", True), (2, "EXPR5", True),
])
def test_a_digital_pin_only_accepts_the_functions_that_pin_has(pin, function, allowed):
    """Measured on the instrument: FAULt is pin 1 only, INHibit pin 3 only, the
    couple functions pins 4-7 only. The guide gives one flat list for all pins."""
    async def body():
        backend, fake = await connected_backend()
        fake.messages.clear()
        if allowed:
            await backend.execute(f"set_digital_pin_function_{pin}", value=function)
            assert fake.messages[0] == f"DIG:PIN{pin}:FUNC {function};:SYST:ERR?"
        else:
            with pytest.raises(HardwareError, match="expected one of"):
                await backend.execute(f"set_digital_pin_function_{pin}", value=function)
            assert fake.messages == [], "an invalid pin/function pair must not reach the wire"
    asyncio.run(body())


